INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320592-ce341', 'stk-user2352', 'CE 341', 'info', '{"desc": "http://www.learnerstv.com/Free-Engineering-Video-lectures-ltv144-Page1.htm\nhttp://www.learnerstv.com/Free-Engineering-Video-lectures-ltv585-Page1.htm\nشروحات أونلاين فيديو مفيدة لشرح محتوى هذا الكورس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-341-transportation-engineering/120678/2", "user": "user2352", "ts": 1390044575000, "tid": 120678, "pn": 2}}', 1390044575000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2967-ce341', 'stk-user2967', 'CE 341', 'doc', '{"docs": [{"id": "stk-dr-f98567", "n": "Dr. S. Al-Senan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 341 - 111\n\nالتحضير :\nبداية كل كلاس … وانتبه اذا قلل عدد الكلاسات من 3 الى 2 فهو يعتبر كل غياب بغياب ونص\n\nطريقة الشرح :\nملفات وورد … يقرا عليك والتمارين يقراها قرايه بس ماتدري وش سالفتها … بس تلقط احيانا معلومات\nالشرح يمشي\n\nالكويزات :\nلايوجد\n\nالمياجر والفاينلات :\nوسط تقريبا … وانتبه من الفاينل نص الاختبار تقريبا رسم\nويجيك افرج ماتدرين من وين جابه … الميجر الاول والثاني نفس الافرج … والترم اللي قبلنا يقولون اغلبنا او كلنا تحت الافرج … شلون حسبه مايدرون\nنقطة مهمه … لاتجي تناقشه عن حلك في بالاختبار وتقول صح علي … نظامه انا الدكتور انا افهم منك واعرف الغلط … سامح لك تناقشه او تبلغه اذا كان فيه خطا بالمجموع\n\nالقريد النهائي:\nd+\n\nالصوت:\nواضح جدا\n\nإضافات :\nبروجكت منتصف الترم ع تقاطع الراشد … مكرر كل ترم … دبر لك اي بروحكت وعدل عليه\nالهومووركات يدري انكم تنقلون ولايقول شي لكن يجي نصف الترم ويصيد الطلاب كلهم الا اللي حلهم مختلف جدا جدا جدا\nويلعب غليكم يجيب لكم هومووركات بوورد بعد مايصيدكم … بس تراها نفس الترم اللي قبلم بس يغير رقم او رقمين عشان يصيد اللي غش 🙂\n\nالنهاية\nموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p969339-ce341", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-s-al-senan/98567/13", "user": "user2967", "ts": 1326756029000, "tid": 98567, "pn": 13}}]}', 1326756029000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-civil_engineer1-ce341', 'stk-civil_engineer1', 'CE 341', 'doc', '{"docs": [{"id": "stk-dr-f98567", "n": "Dr. S. Al-Senan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 341\n\nالتحضير :\nبداية كل كلاس\n\nطريقة الشرح :\nملف وورد يشرح عليه ويكون منزله في الويب سيتي عشان تذاكر منه بس\n\nالكويزات :\nمافيه\n\nالمياجر:\nماراح تتوقع ابدا طريقته في الاسئلة يا يجيب شي مرره تافه لدجة ما كنت متوقع انه يجي وتغلط فيه يالعكس\n\nالفاينلات : نفس المياجر\n\nالقريد النهائي: C+\n\nالصوت: ممتاز\n\nإضافات : الدكتور بكل صراحة مظلوم بالسمعه السيئة … اخلاقه عسل و حبوب و ينكت و شريح ومايقصر في المكتب ويعطي كلاسات اوف لكن قريداته اقل من غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1233291-ce341", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-s-al-senan/98567/16", "user": "civil_engineer1", "ts": 1370769154000, "tid": 98567, "pn": 16}}]}', 1370769154000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
